// UI languages: de/en are built in, every other language is translated once via DeepL (edge function, cached) and kept on the device
const UI_LANGS = ['de','en','fr','es','it','nl','pl','cs','tr','pt','ro','hu','zh'];

const LOCALES = {de:'de-DE', en:'en-GB', fr:'fr-FR', es:'es-ES', it:'it-IT', nl:'nl-NL', pl:'pl-PL', cs:'cs-CZ', tr:'tr-TR', pt:'pt-PT', ro:'ro-RO', hu:'hu-HU', zh:'zh-CN'};

const LOCALE = () => LOCALES[G.LANG] || 'en-GB';

const t = (k, vars) => { let s = (I18N[G.LANG] && I18N[G.LANG][k]) || (G.LANG!=='de' && I18N.en[k]) || I18N.de[k] || k; if(vars) for(const v in vars) s = s.replace('{'+v+'}', vars[v]); return s; };

const fmtDate = d => new Date(d).toLocaleString(LOCALE(), {dateStyle:'medium', timeStyle:'short'});

const fmtD = d => new Date(d).toLocaleDateString(LOCALE(), {dateStyle:'medium'});

const UI_SKIP = new Set(['app','lang','sec']);

const uiEntries = () => Object.entries(I18N.de).filter(([k,v]) => typeof v==='string' && !UI_SKIP.has(k)).map(([k,v]) => ({k, v}));

async function loadUiLang(lang){
  const l = String(lang||'').toLowerCase(); if(!l || I18N[l]) return true; if(!UI_LANGS.includes(l) || !G.sb) return false;
  const items = uiEntries(); const h = strHash(items.map(x=>x.v).join('\u0001'));
  const cached = LS.get('gg_ui_'+l); if(cached && cached.h===h && cached.map){ I18N[l] = Object.assign({}, I18N.de, cached.map); return true; }
  try{ const {data, error} = await G.sb.functions.invoke('translate', {body:{ui:items, target:l.toUpperCase()}}); if(error) throw new Error(error.message||String(error)); if(!data || !data.map) throw new Error((data&&data.error)||'ui translate failed');
    I18N[l] = Object.assign({}, I18N.de, data.map); LS.set('gg_ui_'+l, {h, map:data.map}); return true; }
  catch(e){ toast('DeepL: '+e.message); return false; }
}

const uiLangList = () => [['DE','Deutsch'],['EN','English'], ...LANGS.filter(([k]) => k!=='DE' && k!=='EN')];

function langMenu(onPick){ return modal(`<h2>${t('language')}</h2><div class="menu langmenu">${uiLangList().map(([k,name]) => `<button data-l="${k}" class="${G.LANG===k.toLowerCase()?'cur':''}"><span class="flag">${FLAGS[k]}</span> ${name}</button>`).join('')}</div>`, (bg, close) => { $$('[data-l]', bg).forEach(b => b.onclick = () => { close(); onPick(b.dataset.l); }); }); }

export { I18N, UI_LANGS, LOCALES, LOCALE, t, fmtDate, fmtD, UI_SKIP, uiEntries, loadUiLang, uiLangList, langMenu };
